\title{Structural Foundations of the Determinant-Bounded Ratio Spectrum of Lagrange Constants}
\author{Aristotle}
\date{2026-06-26}

\begin{document}

\begin{abstract}
For an integer $2 \times 2$ matrix $M = \left(\begin{smallmatrix} p & q \\ r & s\end{smallmatrix}\right)$ with nonzero determinant, acting on the real line by the M\"obius transformation $M\cdot x = (px+q)/(rx+s)$, the \emph{ratio spectrum} is the set of values $k(M\cdot x)/k(x)$, where $k(\cdot)$ is the Lagrange constant measuring rational approximability. The Lagarias--Shallit bounds confine every ratio to $[1/|\det M|,\, |\det M|]$, and the density conjecture asserts these ratios fill the entire interval as $x$ ranges over real quadratic irrational badly approximable numbers. We establish the structural backbone of that program: (i) the integrality bound $|\det M| \ge 1$ and its consequences (the interval is nonempty, contains the neutral ratio $1$, and has reciprocal endpoints); (ii) scaling invariance of the M\"obius action, so only the primitive class of $M$ is visible; (iii) the composition law $M\cdot(N\cdot x) = (MN)\cdot x$ together with determinant multiplicativity, exhibiting the integer matrix monoid acting by partial M\"obius maps; and (iv) closure of the quadratic-irrational locus under the action, supported by an explicit anisotropy discriminant identity. These reduce density to controlling Lagrange constants along periodic continued fractions and to the Smith-normal-form reduction to $\diag(1, |\det M|)$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The Lagrange constant}
The quality of rational approximation to $x \in \R$ is captured by its \emph{Lagrange constant}
\[
k(x) = \limsup_{q \to \infty} \frac{1}{q^2 \lVert q x\rVert},
\qquad \lVert t\rVert = \min_{n\in\Z}|t-n|,
\]
the supremum of $c>0$ with $|x - p/q| < 1/(c q^2)$ for infinitely many coprime $(p,q)$. By Hurwitz, $k(x) \ge \sqrt5$ for irrational $x$, with equality for $x$ equivalent to the golden ratio. A number is \emph{badly approximable} iff $k(x) < \infty$, iff its continued-fraction partial quotients are bounded. The set $\{k(x)\}$ is the Lagrange spectrum.

\subsection{The ratio spectrum}
For $M = \left(\begin{smallmatrix} p & q \\ r & s\end{smallmatrix}\right) \in M_2(\Z)$ with $\det M = ps-qr \ne 0$, the \emph{M\"obius action} is
\[
M \cdot x = \mob(p,q,r,s;x) = \frac{px+q}{rx+s},
\]
defined where $rx+s \ne 0$. For $M \in \GL_2(\Z)$ the action preserves $k$ exactly; in general the ratio $\rho(M,x) = k(M\cdot x)/k(x)$ measures the distortion of approximability. The Lagarias--Shallit bounds state, with $D := |\det M|$,
\begin{equation}\tag{LS}
\frac1D \le \rho(M,x) \le D.
\end{equation}
The \emph{ratio spectrum} is $\Spec(M) = \{\rho(M,x)\}$.

\subsection{The density conjecture}
\begin{conjecture}[Density]
Let $M$ be a primitive integer matrix with $\det M \ne 0$ and $D = |\det M|$. For all reals $u<v$ with $1/D \le u < v \le D$, there is a real quadratic irrational badly approximable $x$ with $u < \rho(M,x) < v$; equivalently $\Spec(M)$ on quadratic irrationals is dense in $[1/D, D]$.
\end{conjecture}
The restriction to quadratic irrationals is natural: by Lagrange they are exactly the reals with eventually periodic continued fractions, for which $k(x)$ is a finite period maximum. The conjecture is open; we establish its structural backbone in four pillars: interval geometry (\S\ref{sec:interval}), primitivity (\S\ref{sec:prim}), monoid action (\S\ref{sec:monoid}), closure (\S\ref{sec:closure}).

\section{Definitions}

\begin{definition}[M\"obius action]
For $p,q,r,s \in \Z$, $x \in \R$: $\mob(p,q,r,s;x) = \frac{px+q}{rx+s}$, defined where $rx+s \ne 0$.
\end{definition}
\begin{definition}[Determinant and interval]
$\det M = ps - qr$, $D := |ps-qr|$, target interval $I(M) = [1/D, D]$.
\end{definition}
\begin{definition}[Quadratic irrational]
$\QuadIrr(x)$ holds iff $x$ is irrational and $a x^2 + b x + c = 0$ for some $a,b,c \in \Z$ with $a \ne 0$; equivalently $x$ has an eventually periodic continued fraction.
\end{definition}
\begin{definition}[Primitive matrix]
$M$ is \emph{primitive} iff $\gcd(p,q,r,s) = 1$.
\end{definition}

\section{Geometry of the target interval}\label{sec:interval}

\begin{theorem}[Integrality bound]
If $ps-qr \ne 0$ then $1 \le |ps-qr|$ in $\Z$, hence in $\R$.
\end{theorem}
\begin{proof}[Proof sketch]
A nonzero integer has absolute value $\ge 1$; casting into $\R$ preserves the inequality.
\end{proof}

\begin{theorem}[Neutral ratio in interval]
If $ps-qr \ne 0$ then $1/D \le 1$ and $1 \le D$.
\end{theorem}
\begin{proof}[Proof sketch]
$D \ge 1$ gives $1 \le D$ and, dividing $1$ by a quantity $\ge 1$, $1/D \le 1$. Thus $1 \in I(M)$.
\end{proof}

\begin{theorem}[Nonemptiness]
If $ps-qr\ne 0$ then $1/D \le D$.
\end{theorem}
\begin{proof}[Proof sketch]
For $D>0$, $1/D \le D \iff 1 \le D^2$, which follows from $D \ge 1$.
\end{proof}

\begin{theorem}[Reciprocal endpoints]
If $ps - qr \ne 0$ then $\dfrac1D \cdot D = 1$.
\end{theorem}
\begin{proof}[Proof sketch]
$D \ge 1 > 0$ is a nonzero real, so $(1/D)\cdot D = 1$. Hence $I(M)$ is invariant under $\rho \mapsto 1/\rho$, reflecting the $M \leftrightarrow M^{-1}$ symmetry.
\end{proof}

\section{Primitivity is the correct normalization}\label{sec:prim}

\begin{theorem}[Scaling invariance]
For every nonzero integer $k$ and all $p,q,r,s\in\Z$, $x\in\R$:
\[
\mob(kp,kq,kr,ks;x) = \mob(p,q,r,s;x).
\]
\end{theorem}
\begin{proof}[Proof sketch]
$\frac{(kp)x+(kq)}{(kr)x+(ks)} = \frac{k(px+q)}{k(rx+s)} = \frac{px+q}{rx+s}$; the common nonzero factor $k$ cancels for every $x$.
\end{proof}

\begin{corollary}[Reduction to primitive matrices]
Writing $M = k M_0$ with $k=\gcd(p,q,r,s)$ and $M_0$ primitive, $M\cdot x = M_0\cdot x$, so $\Spec(M) = \Spec(M_0)$. The spectral invariant is $|\det M_0|$, not $|\det M| = k^2|\det M_0|$.
\end{corollary}

\section{The integer matrix monoid acts by M\"obius maps}\label{sec:monoid}

\begin{theorem}[Determinant multiplicativity]
For all integer entries,
\[
(pp'+qr')(rq'+ss') - (pq'+qs')(rp'+sr') = (ps-qr)(p's'-q'r').
\]
\end{theorem}
\begin{proof}[Proof sketch]
A finite polynomial identity in the eight entries, verified by ring normalization.
\end{proof}

\begin{theorem}[Composition law]
With $M = \left(\begin{smallmatrix} p&q\\r&s\end{smallmatrix}\right)$, $N=\left(\begin{smallmatrix} p'&q'\\r'&s'\end{smallmatrix}\right)$, if $r'x+s'\ne 0$ and $(rp'+sr')x+(rq'+ss')\ne 0$, then
\[
M\cdot(N\cdot x) = (MN)\cdot x, \qquad
MN = \begin{pmatrix} pp'+qr' & pq'+qs' \\ rp'+sr' & rq'+ss'\end{pmatrix}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Substitute $N\cdot x = (p'x+q')/(r'x+s')$ into $M\cdot(\cdot)$ and multiply through by $r'x+s'\ne 0$:
\[
\frac{p(p'x+q')+q(r'x+s')}{r(p'x+q')+s(r'x+s')} = \frac{(pp'+qr')x+(pq'+qs')}{(rp'+sr')x+(rq'+ss')} = (MN)\cdot x.
\]
Both denominator hypotheses are required.
\end{proof}

\begin{corollary}[Monoid structure; closure of the bound]
Nonzero-determinant integer matrices act on $\R$ by partial M\"obius maps with composition mirroring matrix product. Since ratios multiply along composition and $|\det(MN)| = |\det M||\det N|$, the bound (LS) is closed under composition. With $M = U\,\diag(1,D)\,V$, $U,V \in \GL_2(\Z)$ (Smith normal form) preserving $k$, all spectral content lies in $\diag(1,D)$.
\end{corollary}

\section{Closure of the quadratic-irrational locus}\label{sec:closure}

\begin{lemma}[Anisotropy via discriminant identity]
Let $a,b,c\in\Z$, $a\ne 0$, with $at^2+bt+c$ having an irrational root. Then $a m^2 - b m n + c n^2 = 0$ has no nontrivial integer solution.
\end{lemma}
\begin{proof}[Proof sketch]
From $4a(am^2-bmn+cn^2) = (2am-bn)^2 - (b^2-4ac)n^2$: irrationality forces $b^2-4ac$ non-square. A nontrivial zero would make $b^2-4ac$ a rational, hence integer, square (if $n\ne 0$) or force $m=n=0$ (if $n=0$) --- contradiction.
\end{proof}

\begin{theorem}[Irrationality preserved]
If $x$ is irrational, $ps-qr\ne 0$, $rx+s\ne 0$, then $M\cdot x$ is irrational.
\end{theorem}
\begin{proof}[Proof sketch]
If $M\cdot x = a/b \in \Q$ then $(bp-ar)x = as-bq$; a nonzero coefficient of $x$ would make $x$ rational, while a zero coefficient combined with $\det M\ne 0$ yields a contradiction.
\end{proof}

\begin{theorem}[Closure]
If $\QuadIrr(x)$, $ps-qr\ne 0$, denominator nonzero, then $\QuadIrr(M\cdot x)$.
\end{theorem}
\begin{proof}[Proof sketch]
Irrationality is the previous theorem. The inverse M\"obius map (integer coefficients, determinant $\pm(ps-qr)\ne 0$) expresses $x$ rationally in $y = M\cdot x$; substituting into $ax^2+bx+c=0$ and clearing denominators gives $Ay^2+By+C=0$ with $A\ne 0$ guaranteed by the nonzero determinant. Hence $y$ is a quadratic irrational.
\end{proof}

\section{Algorithms}

\textbf{Lagrange constant via period maximum.} For periodic continued fraction $[a_0;\dots,\overline{a_{m+1},\dots,a_{m+\ell}}]$,
\[
k(x) = \max_i\bigl([0;a_{i-1},a_{i-2},\dots] + [a_i;a_{i+1},\dots]\bigr),
\]
a finite max over one period; complexity $O(\ell P)$ for truncation depth $P$.

\textbf{Smith normal form reduction.} Compute $U,V\in\GL_2(\Z)$, $D_1\mid D_2$, with $M = U\diag(D_1,D_2)V$ by Euclid on entries; for primitive $M$, $D_1=1$, $D_2 = D$, so $\Spec(M) = \Spec(\diag(1,D))$.

\textbf{Ratio-spectrum sampler.} Enumerate bounded-height periodic continued fractions, form $x$, apply $M$, compute $k(x), k(M\cdot x)$, record $\rho(M,x)$; the empirical distribution converges to a dense subset of $[1/D,D]$.

\section{Applications and discussion}
The monoid action situates the spectrum within $\GL_2$-actions on the hyperbolic boundary; the reciprocal endpoints are the spectral imprint of $M\leftrightarrow M^{-1}$ duality. Since $\GL_2(\Z)$ acts trivially on $k$ while $\diag(1,D)$ carries the full effect, distortion questions reduce to one diagonal family. The anisotropy identity is the entry point to a positive-measure refinement. The density conjecture itself remains open; our contribution renders it a precise problem about a monoid acting on a stable class.

\section{Future directions}
\textbf{FD1.} The two-sided bound is attained in the limit on periodic continued fractions, with extremes realized by periods aligned with $\diag(1,D)$.\\
\textbf{FD2.} Density reduces to $\diag(1,D)$ via Smith normal form, using $k$-preserving $\GL_2(\Z)$ factors and the multiplicative action.\\
\textbf{FD3.} Anisotropy controls the measure of attainable ratios: bounded-height ratios have positive measure in $[1/D,D]$, tending to full measure.\\
\textbf{FD4.} The $M\leftrightarrow M^{-1}$ reciprocal symmetry is exact: $\rho \in \Spec(M) \iff 1/\rho \in \Spec(M^{-1})$.

\section{Conclusion}
We established the rigid structural foundation of the determinant-bounded ratio spectrum: $[1/D,D]$ is nonempty, contains $1$, and is self-reciprocal (forced by $|\det M|\ge 1$); the action is scale-invariant (primitivity is the correct normalization); integer matrices act as a monoid by partial M\"obius maps with multiplicative determinants; and the quadratic-irrational locus is closed. These convert the density conjecture into a precisely posed problem with an explicit reduction strategy.

