from typing import Tuple

Matrix = Tuple[int, int, int, int]

def det(M: Matrix) -> int:
    p, q, r, s = M
    return p * s - q * r

def mobius(M: Matrix, x: float) -> float:
    p, q, r, s = M
    return (p * x + q) / (r * x + s)

def mat_mul(M: Matrix, N: Matrix) -> Matrix:
    p, q, r, s = M
    p2, q2, r2, s2 = N
    return (p*p2+q*r2, p*q2+q*s2, r*p2+s*r2, r*q2+s*s2)

def demo() -> None:
    M, N = (3,1,2,1), (3,0,1,2)
    for k in (2, -3, 7):
        kM = tuple(k*e for e in M)
        print('scale k=', k, 'diff=',
              abs(mobius(kM, 1.4142) - mobius(M, 1.4142)))
    MN = mat_mul(M, N)
    for x in (0.3, 1.4142, 2.7183):
        print('compose x=', x, 'diff=',
              abs(mobius(M, mobius(N, x)) - mobius(MN, x)),
              'det check:', det(MN) == det(M)*det(N))

if __name__ == '__main__':
    demo()

